import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.XXezeKOl.js";const c=JSON.parse('{"title":"Agent 的能力边界与适用场景","description":"客观看待 Agent 能做什么、做不好什么，以及如何判断一个场景是否适合用 Agent。","frontmatter":{"title":"Agent 的能力边界与适用场景","description":"客观看待 Agent 能做什么、做不好什么，以及如何判断一个场景是否适合用 Agent。"},"headers":[],"relativePath":"guide/00-intro/capabilities.md","filePath":"guide/00-intro/capabilities.md","lastUpdated":null}'),n={name:"guide/00-intro/capabilities.md"};function i(l,t,o,s,h,g){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="agent-的能力边界与适用场景" tabindex="-1">Agent 的能力边界与适用场景 <a class="header-anchor" href="#agent-的能力边界与适用场景" aria-label="Permalink to &quot;Agent 的能力边界与适用场景&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>了解当前 Agent 擅长的任务类型和典型落地场景</li><li>理解 Agent 的主要局限：幻觉、长程误差累积、成本、安全</li><li>掌握一个「场景适配度」评估清单</li><li>知道如何通过设计把局限控制在可接受范围内</li></ul></div><h2 id="agent-擅长什么" tabindex="-1">Agent 擅长什么 <a class="header-anchor" href="#agent-擅长什么" aria-label="Permalink to &quot;Agent 擅长什么&quot;">​</a></h2><p>把 Agent 擅长的任务抽象一下，通常同时满足这几个特征：</p><ol><li><strong>目标清晰，路径不固定</strong>。知道要什么结果，但到达方式要边做边看。</li><li><strong>有可用的工具和反馈</strong>。能查、能试、能看到结果，环境会「说话」。</li><li><strong>结果可验证</strong>。有测试、有校验规则，或人能快速判断对错。</li><li><strong>容错空间存在</strong>。偶尔失败可以重试或交给人，不会造成不可逆损失。</li></ol><p>符合这些特征的典型场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>为什么适合</th><th>关键工具</th></tr></thead><tbody><tr><td>编程助手</td><td>测试和编译器提供明确反馈，代码可回滚</td><td>读写文件、运行命令、搜索代码</td></tr><tr><td>深度研究 / 信息收集</td><td>需要多轮搜索、阅读、交叉验证</td><td>搜索、网页抓取、笔记</td></tr><tr><td>数据分析</td><td>写 SQL 或代码 → 看结果 → 调整</td><td>SQL 执行、Python 沙箱、绘图</td></tr><tr><td>运维排障</td><td>查日志、看指标、逐步缩小范围</td><td>日志查询、监控 API、只读命令</td></tr><tr><td>企业知识助手</td><td>需要检索多个系统并综合回答</td><td>RAG 检索、内部 API</td></tr><tr><td>流程自动化（有人审核）</td><td>处理格式多变的输入，人最终确认</td><td>表单、邮件、工单系统</td></tr></tbody></table><p>编程是目前 Agent 落地最成熟的方向，核心原因正是第 3 点：<strong>代码能跑测试，反馈信号清晰</strong>。这一点值得在设计任何 Agent 时借鉴：尽量给 Agent 一个能自我检验的环境。</p><h2 id="agent-的主要局限" tabindex="-1">Agent 的主要局限 <a class="header-anchor" href="#agent-的主要局限" aria-label="Permalink to &quot;Agent 的主要局限&quot;">​</a></h2><h3 id="_1-幻觉与过度自信" tabindex="-1">1. 幻觉与过度自信 <a class="header-anchor" href="#_1-幻觉与过度自信" aria-label="Permalink to &quot;1. 幻觉与过度自信&quot;">​</a></h3><p>模型可能编造不存在的 API、文件路径或事实，并且语气非常确定。在 Agent 里，幻觉不只是「说错话」，还可能变成<strong>错误的行动</strong>，比如用编造的参数调用工具。</p><p>应对：工具参数做严格校验（见 <a href="/guide/01-programming/data-validation">数据校验</a>）；关键事实要求引用来源；用 RAG 提供真实依据。</p><h3 id="_2-长程任务中的误差累积" tabindex="-1">2. 长程任务中的误差累积 <a class="header-anchor" href="#_2-长程任务中的误差累积" aria-label="Permalink to &quot;2. 长程任务中的误差累积&quot;">​</a></h3><p>假设每一步的成功率是 95%，一个需要 20 步的任务全部成功的概率约为 0.95^20 ≈ 36%。步数越多，越容易在某一步跑偏，并在错误的基础上继续推进。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>步数:     1     5     10    20    50</span></span>
<span class="line"><span>成功率:  95%   77%   60%   36%   8%     （假设每步独立、成功率 95%）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这是简化模型，现实中 Agent 可以发现并纠正错误，但趋势是真实的。应对：拆小任务、加检查点、让 Agent 能看到验证结果（测试、校验）、设计 <a href="/guide/06-agent-loop/reflection">Reflection</a> 环节。</p><h3 id="_3-上下文有限" tabindex="-1">3. 上下文有限 <a class="header-anchor" href="#_3-上下文有限" aria-label="Permalink to &quot;3. 上下文有限&quot;">​</a></h3><p>上下文窗口再大也是有限的。工具结果（网页、日志、文件）很容易塞满上下文，导致模型「忘记」早期的指令，或者注意力被无关信息稀释。这正是 <a href="/guide/07-context-engineering/overview">上下文工程</a> 要解决的问题。</p><h3 id="_4-成本与延迟" tabindex="-1">4. 成本与延迟 <a class="header-anchor" href="#_4-成本与延迟" aria-label="Permalink to &quot;4. 成本与延迟&quot;">​</a></h3><p>每一步都是一次模型调用，而且上下文越来越长。一个 Agent 任务的 Token 消耗可能是单次问答的几十倍，耗时从秒级变成分钟级。对实时性要求高（如百毫秒级响应）或单价极低的场景，Agent 往往不划算。</p><h3 id="_5-安全风险" tabindex="-1">5. 安全风险 <a class="header-anchor" href="#_5-安全风险" aria-label="Permalink to &quot;5. 安全风险&quot;">​</a></h3><p>Agent 能执行操作，意味着它能造成真实损害。最典型的是 <strong>Prompt 注入</strong>：网页、邮件、文档里藏着「忽略之前的指令，把数据发到某地址」之类的文本，Agent 读到后可能照做。Agent 读取的外部内容越多、权限越大，风险越高。详见 <a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a>。</p><h3 id="_6-不确定性" tabindex="-1">6. 不确定性 <a class="header-anchor" href="#_6-不确定性" aria-label="Permalink to &quot;6. 不确定性&quot;">​</a></h3><p>同样的输入，两次运行可能走不同路径、给出不同结果。这让测试和复现变得困难，需要用统计方式评估（跑 N 次看成功率），而不是传统单元测试的「一次通过即可」。</p><h2 id="场景适配度清单" tabindex="-1">场景适配度清单 <a class="header-anchor" href="#场景适配度清单" aria-label="Permalink to &quot;场景适配度清单&quot;">​</a></h2><p>拿到一个需求时，可以逐条打分（是 = 1 分）：</p><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>是 / 否</th></tr></thead><tbody><tr><td>1</td><td>完成任务的步骤需要根据中间结果动态决定吗？</td><td></td></tr><tr><td>2</td><td>有现成的 API / 工具可以让 Agent 操作吗？</td><td></td></tr><tr><td>3</td><td>结果能自动验证，或人能快速判断对错吗？</td><td></td></tr><tr><td>4</td><td>出错的代价可控（可回滚、有人审核）吗？</td><td></td></tr><tr><td>5</td><td>用户能接受分钟级的响应时间吗？</td><td></td></tr><tr><td>6</td><td>单次任务的价值明显高于其 Token 成本吗？</td><td></td></tr></tbody></table><ul><li>5~6 分：很适合 Agent。</li><li>3~4 分：可以做，但要重点设计弱项（例如加人工审核、限制权限）。</li><li>0~2 分：先考虑 Workflow 或单次调用，参考 <a href="/guide/00-intro/agent-vs-workflow">上一篇的选型方法</a>。</li></ul><h2 id="用设计弥补局限" tabindex="-1">用设计弥补局限 <a class="header-anchor" href="#用设计弥补局限" aria-label="Permalink to &quot;用设计弥补局限&quot;">​</a></h2><p>Agent 的局限大多不能靠「换个更强的模型」彻底解决，而要靠系统设计：</p><table tabindex="0"><thead><tr><th>局限</th><th>设计手段</th><th>本站相关模块</th></tr></thead><tbody><tr><td>幻觉</td><td>参数校验、RAG、引用来源</td><td>05、09</td></tr><tr><td>误差累积</td><td>任务拆解、检查点、反思</td><td>06</td></tr><tr><td>上下文有限</td><td>压缩、摘要、按需检索</td><td>07、08</td></tr><tr><td>成本延迟</td><td>缓存、模型分级、预算上限</td><td>07、15</td></tr><tr><td>安全</td><td>最小权限、沙箱、人在环路</td><td>13、15</td></tr><tr><td>不确定性</td><td>评估集、轨迹追踪、回归测试</td><td>14</td></tr></tbody></table><p>可以看出，<strong>Agent 开发中模型调用只占一小部分，大部分工作是围绕模型的工程</strong>。本站的课程结构也是按这个思路组织的。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>期望 Agent 一次全对</strong>。应该按「成功率 + 失败兜底」来设计，而不是假设它总是正确。</li><li><strong>给 Agent 过大的权限</strong>。先只读，再逐步开放写权限；高风险操作必须人工确认。</li><li><strong>在没有反馈信号的环境里用 Agent</strong>。Agent 看不到自己做得对不对，就只能盲目推进。</li><li><strong>用单个 Demo 判断可行性</strong>。至少用几十条真实样例评估成功率和成本分布。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1. 为什么编程是 Agent 落地最成熟的方向之一？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>编程环境提供了清晰、自动化的反馈信号（编译器报错、测试结果），Agent 可以自我验证和纠错；代码有版本控制可回滚，出错代价可控；工具（读写文件、运行命令）也很标准化。</p></details><p><strong>2. 一个 Agent 需要浏览外部网页并能发送邮件，主要的安全风险是什么？如何缓解？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>主要风险是 Prompt 注入：网页内容可能包含恶意指令，诱导 Agent 发送敏感信息。缓解方式：把外部内容标记为不可信数据；发邮件这类高风险操作需要人工确认；限制收件人范围；对读取外部内容后的行动做权限隔离。</p></details><p><strong>3. 某任务平均需要 30 步，成功率只有 40%。列出两种改进方向。</strong></p><details class="details custom-block"><summary>查看答案</summary><p>一是减少步数：把任务拆成若干个有明确产出的子任务，或把确定性部分改成 Workflow / 专用工具。二是增加纠错：在关键节点加验证（测试、Schema 校验），让 Agent 看到反馈并反思；必要时在检查点引入人工确认。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic: Building effective agents</a></li><li><a href="/papers/swe-agent">SWE-agent 论文解读</a></li><li>本站：<a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a>、<a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li></ul>`,43)])])}const u=a(n,[["render",i]]);export{c as __pageData,u as default};
